var cluster = new api.THREE.Group();
                var offsets = [[0.05,0.03],[ -0.04,0.05],[0.02,-0.05],[-0.03,-0.03],[0.06,0.01]];
                for (var i = 0; i < offsets.length; i++) {
                  var sphere = new api.THREE.Mesh(
                    new api.THREE.SphereGeometry(0.06, 16, 16),
                    new api.THREE.MeshPhongMaterial({ color: 0x2E86AB })
                  );
                  sphere.position.set(offsets[i][0], offsets[i][1], 0);
                  cluster.add(sphere);
                }
                api.group.add(cluster);
                return {
                  update: function(t) {
                    cluster.rotation.y = t * 0.02;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W / 2 + 70, cy = H / 2 - 50;
                    ctx.strokeStyle = '#94A3B8';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(W / 2, H / 2 - 15);
                    ctx.lineTo(W / 2 + 15, H / 2);
                    ctx.moveTo(W / 2 - 15, H / 2);
                    ctx.lineTo(W / 2 + 15, H / 2);
                    ctx.moveTo(W / 2, H / 2 - 15);
                    ctx.lineTo(W / 2, H / 2 + 15);
                    ctx.stroke();
                    var seed = Math.floor(t / 40);
                    for (var d = 0; d < 5; d++) {
                      var jx = ((seed * 3 + d * 11) % 10) - 5;
                      var jy = ((seed * 5 + d * 7) % 10) - 5;
                      ctx.fillStyle = '#E8593C';
                      ctx.beginPath();
                      ctx.arc(cx + jx, cy + jy, 5, 0, Math.PI * 2);
                      ctx.fill();
                    }
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W / 2 + 60, cy = H / 2 - 40;
                    ctx.fillStyle = '#111827';
                    ctx.font = '12px sans-serif';
                    ctx.fillText('True value', 20, 20);
                    ctx.beginPath();
                    ctx.arc(W / 2, H / 2, 4, 0, Math.PI * 2);
                    ctx.fillStyle = '#2E86AB';
                    ctx.fill();
                    var spread = controls.spread !== undefined ? controls.spread : 8;
                    var count = controls.throws !== undefined ? controls.throws : 6;
                    for (var d = 0; d < count; d++) {
                      var jx = ((d * 37) % (spread * 2 + 1)) - spread;
                      var jy = ((d * 53) % (spread * 2 + 1)) - spread;
                      ctx.fillStyle = '#E8593C';
                      ctx.beginPath();
                      ctx.arc(cx + jx, cy + jy, 5, 0, Math.PI * 2);
                      ctx.fill();
                    }
                  }
                };
